  /// <summary>Westfall-Young single-step minP adjustment (Westfall &amp; Young, 1993) -- a resampling-        based FWER correction that accounts for the actual dependence structure between        tests (unlike the analytic methods above, which either assume independence or make        no assumption at all).</summary>
  ///         ``resampled_p`` is a B x m matrix: row b holds the m p-values recomputed on the
  ///         b-th permutation or bootstrap resample (generated by the caller -- this function is
  ///         purely the combinatorial engine, not the resampling scheme itself). ``sorted_p`` is
  ///         the m original p-values sorted ascending, and column k of every row in ``resampled_p``
  ///         must correspond to the same hypothesis as sorted_p[k] (i.e. the caller sorts once and
  ///         reorders both consistently before calling).
  ///         Single-step: every hypothesis is compared against the same reference distribution --
  ///         the per-resample minimum p-value taken over *all* m hypotheses -- so adjusted p[k] =
  ///         (fraction of resamples whose overall minimum p-value &lt;= sorted_p[k]). This is
  ///         automatically monotonic in sorted_p and valid under subset pivotality, but less
  ///         powerful than the step-down refinement below since it never narrows the comparison
  ///         set as hypotheses are resolved.
  ///         Returned in the same (ascending sorted_p) order as the input; the caller is
  ///         responsible for mapping back to original hypothesis order if needed.
  public static DVector westfall_young_adjust(DVectorVector resampled_p, DVector sorted_p) {
    DVector ret = new DVector(datamungePINVOKE.westfall_young_adjust(DVectorVector.getCPtr(resampled_p), DVector.getCPtr(sorted_p)), true);
    if (datamungePINVOKE.SWIGPendingException.Pending) throw datamungePINVOKE.SWIGPendingException.Retrieve();
    return ret;
  }

  /// <summary>Romano-Wolf step-down resampling adjustment (Romano &amp; Wolf, 2005) -- like        westfall_young_adjust, but more powerful: at each step k (in ascending sorted_p        order), the reference distribution is the per-resample minimum p-value taken only        over the *remaining* hypotheses k..m-1, narrowing by one hypothesis at each step        rather than always using all m. This is the step-down generalization that controls        FWER without requiring subset pivotality. Monotonicity (adjusted p[k] &gt;= adjusted        p[k-1]) is enforced explicitly, since narrowing the comparison set at each step means        it isn't automatic the way it is for the single-step procedure above.</summary>
  ///         Same input/output conventions as westfall_young_adjust: ``resampled_p`` is a B x m
  ///         matrix with column k aligned to sorted_p[k], and the result is returned in the same
  ///         sorted order.
  public static DVector romano_wolf_adjust(DVectorVector resampled_p, DVector sorted_p) {
    DVector ret = new DVector(datamungePINVOKE.romano_wolf_adjust(DVectorVector.getCPtr(resampled_p), DVector.getCPtr(sorted_p)), true);
    if (datamungePINVOKE.SWIGPendingException.Pending) throw datamungePINVOKE.SWIGPendingException.Retrieve();
    return ret;
  }

